def aggregate_workloads(input_dir, output_file, exclude_existing=None):
    """Aggregate workloads from all chunk files in input_dir."""
    chunk_files = sorted(Path(input_dir).glob("workloads_chunk_*.txt"))
    if not chunk_files:
        print(f"No chunk files found in {input_dir}")
        return
    print(f"Found {len(chunk_files)} chunk files")
    all_workloads = []
    for chunk_file in chunk_files:
        with open(chunk_file, 'r') as f:
            workloads = [line.strip() for line in f if line.strip()]
            all_workloads.extend(workloads)
            print(f"  {chunk_file.name}: {len(workloads)} workloads")
    print(f"\nTotal workloads collected: {len(all_workloads)}")
    unique_workloads = set(all_workloads)
    print(f"Unique workloads: {len(unique_workloads)}")
    # Always exclude candidate_set_wkls
    exclude_set = set(CANDIDATE_SET_WKLS)
    if exclude_existing:
        exclude_set.update(exclude_existing)
    filtered_workloads = unique_workloads - exclude_set
    print(f"Candidate set workloads excluded: {len(CANDIDATE_SET_WKLS)}")
    print(f"After filtering: {len(filtered_workloads)} new workloads")
    sorted_workloads = sorted(filtered_workloads)
    with open(output_file, 'w') as f:
        for i, wkl in enumerate(sorted_workloads):
            f.write(f'("workload_{i}", {wkl}),\n')
    print(f"\nOutput written to: {output_file}")
    return sorted_workloads
def main():
    parser = argparse.ArgumentParser(description='Aggregate workloads from chunk files')
    parser.add_argument('--input_dir', type=str, default='wkl_extraction',
                        help='Directory containing workload chunk files')
    parser.add_argument('--output_file', type=str, default='aggregated_workloads.txt',
                        help='Output file for aggregated unique workloads')
    args = parser.parse_args()
    aggregate_workloads(args.input_dir, args.output_file)
if __name__ == "__main__":
    main()
